<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { api, session } from '../../shared/api'
import { showError } from '../../shared/state'
import { addDays, dateTime, roleNames } from '../../shared/format'
import Icon from '../../shared/Icon.vue'
interface Log {id: string; actorName: string; actorRole: string; actionType: string; objectId?: string; orderId?: string; requestId?: string; outcome: string; detail: string; createdAt: string}
const rows = ref<Log[]>([]), object = ref(''), from = ref(addDays(session.today,-14)), to = ref(session.today), busy = ref(false)
const actions: Record<string,string> = {BOOK:'自动预订',CHANGE:'改订',CANCEL:'整单取消',CHECK_IN:'逐人入住',CHECK_OUT:'退房',ACTUAL_NIGHT:'登记实际间夜',INVENTORY_UPDATE:'每日房源调整',CLOSURE:'停业登记',RELOCATE:'替代安置',ACCESS_DENIED:'拒绝越权',CONTACT_ACCESS:'异常查看完整联系方式',ACCOUNT_SAVE:'账号维护',MASTER_HOTEL:'校方审核资料维护',MASTER_DISTANCE:'核实距离',MASTER_SITE:'接待地点维护',MASTER_RULE:'约定费用规则维护',FEE_REVIEW:'核对费用',FEE_RESOLVE:'处理费用争议',LATE_HOLD:'晚到保留',NO_SHOW:'登记未入住',EXTENSION_CONFIRM:'确认续住',EXTENSION_PROPOSE:'提出续住',SPECIAL_CONFIRM:'特殊改订确认',SPECIAL_REQUEST:'特殊改订申请'}
async function load(){busy.value=true;try{rows.value=await api('/audit?'+new URLSearchParams({object:object.value,from:from.value,to:to.value}))}catch(e){showError(e)}finally{busy.value=false}}
Object.assign(actions, {MASTER_HOTEL_DELETE: '删除酒店', MASTER_USER_DELETE: '删除账号'})
onMounted(load)
</script>
<template><div class="page-heading"><div><span class="eyebrow">ACTIVITY & ACCOUNTABILITY</span><h1>操作日志</h1><p>{{ session.user?.role === 'HOTEL' ? '仅展示本酒店相关操作记录。' : '查询关键业务操作、异常处理和越权拒绝记录。' }}</p></div><span class="soft-tag"><Icon name="shield" :size="16"/> 按权限追溯</span></div><section class="card"><form class="filter-bar" @submit.prevent="load"><label>对象、订单或请求编号<input v-model="object" placeholder="可复制业务编号精确查询"/></label><label>开始日期<input v-model="from" type="date" required/></label><label>结束日期<input v-model="to" type="date" :min="from" required/></label><button class="button primary align-end" :disabled="busy">{{ busy ? '查询中…' : '查询日志' }}</button></form><div class="table-wrap"><table><thead><tr><th>时间</th><th>操作者</th><th>动作</th><th>结果</th><th>说明 / 业务关联</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td class="nowrap">{{ dateTime(r.createdAt) }}</td><td>{{ r.actorName }}<small class="cell-sub">{{ roleNames[r.actorRole] || r.actorRole }}</small></td><td>{{ actions[r.actionType] || r.actionType }}</td><td><span class="badge" :class="r.outcome === 'SUCCESS' ? 'badge-checked_in' : 'badge-cancelled'">{{ ({SUCCESS:'成功',DENIED:'已拒绝',REJECTED:'未生效',NEEDS_RECONFIRMATION:'待重新确认',PENDING:'待处理'})[r.outcome as 'SUCCESS'] || r.outcome }}</span></td><td>{{ r.detail }}<small v-if="r.requestId" class="cell-sub mono">请求 {{ r.requestId }}</small><small v-else-if="r.orderId" class="cell-sub mono">订单 {{ r.orderId }}</small></td></tr><tr v-if="!rows.length"><td colspan="5" class="muted">所选范围暂无日志。</td></tr></tbody></table></div><p class="muted small gap-top">最多显示最近300条匹配记录；可缩小日期范围或按业务编号查询。</p></section></template>
